import{z as i,x as A,o as n,c as l,q as e,j as r,D as E,d as B,s as t,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"买方垄断与工资压低","description":"","frontmatter":{"title":"买方垄断与工资压低","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/monopsony-wages.md","filePath":"econ/monopsony-wages.md","lastUpdated":1791063341000}'),p={name:"econ/monopsony-wages.md"};function m(d,a,h,c,_,D){const o=A("Mermaid");return n(),l("div",null,[a[2]||(a[2]=e('<h1 id="买方垄断与工资压低" tabindex="-1">买方垄断与工资压低 <a class="header-anchor" href="#买方垄断与工资压低" aria-label="Permalink to &quot;买方垄断与工资压低&quot;">​</a></h1><div class="epigraph"><p>买方垄断不是教科书的古董：只要工人换雇主有成本，每家厂商面对的都是一条向上的劳动供给曲线，工资系统性地低于边际产品。</p><footer>—— Manning, Monopsony in Motion, 2003；词源见 Robinson, The Economics of Imperfect Competition, 1933</footer></div><p><a href="/econ/reservation-wage-search">上一课</a>把搜寻写成一道路门槛：保留工资决定接受率，接受率决定入职率。本课把同一套摩擦翻到厂商侧：既然换工作要重付搜寻成本，留住的工人就不是从无弹性的总量里抽来的，而是从一条对<strong>本厂</strong>工资敏感的供给曲线里来的。<a href="/econ/labor-demand-mrp">劳动需求课</a>的基准是 \\(w\\) 等于边际产品价值 MRP；本课的缺口是这个等式何时失效，以及失效的缺口——markdown——怎么用数据量出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Robinson 1933 的静态版本：公司镇上一家买家，面对递增的供给 \\(w(L)\\)，多雇一人的边际成本高于工资，最优雇佣停在 \\(\\mathrm{MCL}=\\mathrm{MRP}\\)，工资落在 \\(w \\lt \\mathrm{MRP}\\)。缺口不是背诵这个图形，而是问：在有许多雇主的城市里，压价从哪来。Manning 的答案是摩擦：只要跳槽有成本（搜寻、地点、专用技能、家庭），厂商提薪只留人、降薪只慢走人，每家厂商都面对一条自己专属的、向上倾斜的供给曲线——买方垄断是程度问题，不是有无问题。写成一阶条件：若厂商级供给弹性为 \\(\\varepsilon\\)，则</p> \\[w \\;=\\; \\mathrm{MRP}\\cdot\\frac{\\varepsilon}{1+\\varepsilon}, \\qquad \\mathrm{markdown} \\;=\\; \\frac{\\mathrm{MRP}-w}{\\mathrm{MRP}} \\;=\\; \\frac{1}{1+\\varepsilon}. \\]<p>供给越平（\\(\\varepsilon\\) 越大），越接近竞争；越陡，压得越深。</p>',7)),(n(),r(s,null,{default:E(()=>[t(o,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRIC%5B%22%E8%B7%B3%E6%A7%BD%E6%88%90%E6%9C%AC%E4%B8%8E%E6%90%9C%E5%AF%BB%E6%91%A9%E6%93%A6%22%5D%20--%3E%20ELAS%5B%22%E5%8E%82%E5%95%86%E7%BA%A7%E4%BE%9B%E7%BB%99%E5%BC%B9%E6%80%A7%20%CE%B5%22%5D%0A%20%20CONC%5B%22%E5%9C%B0%E5%9F%9F%E4%B8%8E%E6%8A%80%E8%83%BD%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%20--%3E%20ELAS%0A%20%20ELAS%20--%3E%20MD%5B%22markdown%20%3D%201%20%2F%20(1%20%2B%20%CE%B5)%22%5D%0A%20%20MD%20--%3E%20WLOW%5B%22w%20%E4%BD%8E%E4%BA%8E%20MRP%22%5D%0A%20%20WLOW%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%9C%80%E4%BD%8E%E5%B7%A5%E8%B5%84%E7%9A%84%E4%B8%8B%E9%99%90%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">量级心算：\\(\\varepsilon=1.5\\) 时工资约为边际产品的六成；\\(\\varepsilon=4\\) 也有两成的压价。也就是说，哪怕工人稍有换厂余地，markdown 也不是小数——这把「垄断与否」的争辩换成「弹性多大」的测量。</span></p><p><span class="marginnote">为什么 MRP「看不见」：它等于多雇一人额外创造的产值，但现实里你没法保持其他条件不变地做这个实验。所以实证只能绕道——先测出厂商级供给弹性，再用公式 \\(\\mathrm{markdown}=1/(1+\\varepsilon)\\) 反推缺口，而不是直接量缺口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>markdown 不可直接观测（MRP 看不见），要借弹性反推，两条实证路线。第一条是地域集中：Azar–Marinescu–Steinbaum 在县 \\(\\times\\) 行业层面算雇主集中度，发现集中度更高的本地市场工资系统性更低——把厂商级供给弹性与「附近有几家可去的厂」挂上钩。第二条是纵向流水数据：Manning 的动态买方垄断用雇主–雇员匹配面板估分离与招聘对工资的准弹性——若降薪使离职明显加快、提薪几乎不带来新人，那就是一条陡的本厂供给曲线，弹性反推回 markdown。两条路互相校验：集中度是弹性的截面代理，流水是弹性的直接读数。</p><p><span class="marginnote">「分离弹性」翻译成大白话：工资每压低 1%，离职率会上升百分之几。假如降薪 1% 让月离职率从 3% 跳到 5%，说明工人「用脚投票」的反应强，本厂供给曲线平，压价空间小；若离职率几乎不动，那就是一条陡曲线，厂商压价的余地大。</span></p><p>错在哪：拿 W=MRP 的竞争基准直接算「工资被压了多少」，MRP 本身要用生产函数估，误差会顺着 \\(\\varepsilon\\) 的倒数放大；拿行业平均工资当 \\(w\\)，又把技能构成的变化混进压价里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>摩擦给买方势力的微观与上一课是同一枚硬币：搜寻让工人不能瞬时改换雇主，于是遭遇（match）自带一点双边垄断，议价份额偏向先贴出岗位的一方。对照<a href="/econ/efficiency-wage">效率工资</a>可以看清「不出清」的两个方向：效率工资把工资钉在出清<strong>之上</strong>，用失业当纪律；买方垄断把工资压在 MRP <strong>之下</strong>，用摩擦收租。一个是厂商自愿抬高，一个是厂商策略性压低，两种机制可以在同一市场并存，不要写成互相取消。</p><p>markdown 的存在改写政策几何：法定下限若把工资从压价区间抬向 MRP，就业不必下降甚至可以上升——这正是下一课最低工资文献的机制接口。错在哪：在压价区间里套竞争模型的就业预测，方向都可能反；反过来，把「最低工资无害」直接当买方垄断的证据，又忽略了价格、工时、进入这些调整边际。本课先只钉机制：\\(w\\) 与 MRP 之间有缺口，缺口由弹性决定，弹性可测。</p><p><span class="marginnote">常见误区：以为买方垄断下最低工资必然减少就业。直觉是：工资被压到 MRP 之下时，厂商少雇一人损失的产出大于付给他的工资，法定下限把工资往上抬一点，厂商反而愿意多雇——就业可能不降反升。当然，这只在压价区间内成立，下限越过 MRP 后逻辑就翻转了。</span></p>',10)),(n(),r(s,null,{default:E(()=>[t(o,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20EG%5B%22%E6%95%88%E7%8E%87%E5%B7%A5%E8%B5%84%EF%BC%9A%E5%90%91%E4%B8%8A%E5%81%8F%E7%A6%BB%22%5D%0A%20%20%20%20A%5B%22%E5%8E%82%E5%95%86%E8%87%AA%E6%84%BF%E5%8A%A0%E8%96%AA%22%5D%20--%3E%20B%5B%22%E5%B7%A5%E8%B5%84%E9%AB%98%E4%BA%8E%E5%87%BA%E6%B8%85%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E4%BB%A5%E5%A4%B1%E4%B8%9A%E4%BD%9C%E7%BA%AA%E5%BE%8B%22%5D%0A%20%20end%0A%20%20subgraph%20MO%5B%22%E4%B9%B0%E6%96%B9%E5%9E%84%E6%96%AD%EF%BC%9A%E5%90%91%E4%B8%8B%E5%81%8F%E7%A6%BB%22%5D%0A%20%20%20%20D%5B%22%E5%8E%82%E5%95%86%E7%AD%96%E7%95%A5%E6%80%A7%E5%8E%8B%E4%BB%B7%22%5D%20--%3E%20E%5B%22%E5%B7%A5%E8%B5%84%E4%BD%8E%E4%BA%8E%20MRP%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E4%BB%A5%E8%B7%B3%E6%A7%BD%E6%91%A9%E6%93%A6%E6%94%B6%E7%A7%9F%22%5D%0A%20%20end%0A%20%20C%20--%3E%20G%5B%22%E4%B8%A4%E7%A7%8D%E4%B8%8D%E5%87%BA%E6%B8%85%E5%8F%AF%E5%B9%B6%E5%AD%98%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给反垄断执法的操作清单：集中度阈值是行政筛子，门槛之内弹性仍可能很大，写成「高集中即压价」会误伤规模经济。流水数据的识别也有坑：提薪本身内生（留人加薪发生在离职风险高的岗位），面板系数要往弹性上读，得先处理这类选择。专用性投资引出的另一种压价走<a href="/econ/hold-up-gh">套牢</a>的合同与所有权通道，不在本课。跨区域的工资套利、移民与最低工资的交互，留待政策课。</p><p>后课默认：厂商面对向上供给、\\(w\\) 低于 MRP 是基准情形而非特例；一切工资下限政策的讨论从这条几何出发。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摩擦使每家厂商面对向上的劳动供给：\\(w = \\mathrm{MRP}\\cdot\\varepsilon/(1+\\varepsilon)\\)。</li><li>markdown 用两条路测：地域集中度对照（Azar 等）与纵向流水的分离弹性（Manning）。</li><li>买方垄断压价与效率工资抬价是两个方向的「不出清」，可并存。</li><li>压价区间里的政策几何与竞争模型不同，为下一课铺垫。</li><li>出处：Robinson 1933；Manning 2003；Azar–Marinescu–Steinbaum 的劳动市场集中度测算。</li></ul>',5))])}const P=i(p,[["render",m]]);export{f as __pageData,P as default};
